import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.B2ul6ABY.js";const h=JSON.parse('{"title":"Second Codebase Review Remediation Cycle","description":"","frontmatter":{},"headers":[],"relativePath":"historical/2026-05-remediation-dossiers/second-codebase-review-remediation-cycle.md","filePath":"historical/2026-05-remediation-dossiers/second-codebase-review-remediation-cycle.md"}'),n={name:"historical/2026-05-remediation-dossiers/second-codebase-review-remediation-cycle.md"};function r(s,e,d,c,l,u){return a(),o("div",null,[...e[0]||(e[0]=[i('<blockquote><p><strong>Historical/Audit Artifact — Not Current Operator Instructions</strong><br> This page records an audit or remediation artifact from an earlier stage. It is not authoritative for current Saivage v3 behavior unless a current active doc explicitly revalidates it against current source and tests.</p></blockquote><h1 id="second-codebase-review-remediation-cycle" tabindex="-1">Second Codebase Review Remediation Cycle <a class="header-anchor" href="#second-codebase-review-remediation-cycle" aria-label="Permalink to &quot;Second Codebase Review Remediation Cycle&quot;">​</a></h1><p>This cycle followed the same review-plan-fix-validate loop as the first full remediation pass, with special attention to the live analyst conversation quality and agent context propagation.</p><h2 id="findings" tabindex="-1">Findings <a class="header-anchor" href="#findings" aria-label="Permalink to &quot;Findings&quot;">​</a></h2><ol><li>Dashboard chat submitted each user message through both WebSocket and REST. The WebSocket response format was not consumed by the Dashboard, so REST was used for the visible reply while both transports persisted and executed the same analyst turn.</li><li>The analyst <code>create_card</code> tool treated an omitted parent as the literal card ID <code>undefined</code>, producing <code>Parent card &#39;undefined&#39; does not exist</code> instead of recovering from the live card tree.</li><li>The analyst LLM resolver had a generic prompt and did not receive compact project/card context, making it likely to answer simple visibility questions generically or invent missing parent IDs.</li><li>The regex fallback did not understand natural queries such as “can you see the current cards?” or “what are the project objectives?”.</li><li>Runtime agent context was goal-local. Planner, executor, reviewer, and continuous-improvement planner calls did not all include the root project card alongside the active goal/card context.</li><li><code>StuckAgentSupervisor.start()</code> created an untracked startup timeout, and <code>process-runner</code> created a cleanup timeout without <code>unref()</code>, leaving clean test runs with open handles.</li><li>Live browser validation found a final analyst intent issue: phrases like “code card under goal-2” could be resolved as type <code>goal</code> because the parent ID contained the word <code>goal</code>.</li></ol><h2 id="plan" tabindex="-1">Plan <a class="header-anchor" href="#plan" aria-label="Permalink to &quot;Plan&quot;">​</a></h2><ol><li>Make chat single-transport: use WebSocket when connected and REST only as an offline fallback; consume the WebSocket analyst response directly in the Dashboard.</li><li>Add a backend duplicate guard so simultaneous submissions of the same analyst turn do not execute or persist twice.</li><li>Harden <code>create_card</code> parent handling by defaulting top-level goals to <code>project</code> and terminal work to the active or only goal when possible.</li><li>Improve analyst prompt and fallback intents with live project/card context, explicit card-parent rules, and direct handling of cards/objectives questions.</li><li>Enrich planner, executor, reviewer, and continuous-improvement planner calls with root project context.</li><li>Clean timer lifecycle issues and verify with <code>--detectOpenHandles</code>.</li><li>Preserve explicit card types in create-card requests even when parent IDs contain another card type word.</li><li>Rebuild, restart the live service, and hold a browser-driven analyst conversation to verify no duplicated messages and useful project control.</li></ol><h2 id="implemented-fixes" tabindex="-1">Implemented Fixes <a class="header-anchor" href="#implemented-fixes" aria-label="Permalink to &quot;Implemented Fixes&quot;">​</a></h2><ul><li>Dashboard chat now sends over one transport per user action and renders WebSocket <code>ChatMessage</code> responses.</li><li><code>AnalystHandler</code> serializes per-session message handling and returns the existing assistant answer for a duplicate same-content turn received within a short window.</li><li><code>create_card</code> now normalizes missing/blank/null-ish parents and selects safe defaults from the card tree.</li><li>Analyst tool schema and LLM prompt now describe parent rules and require inspection for current cards/objectives.</li><li>Planner, executor, reviewer, and continuous-improvement planner invocations now include the root project card context in their runtime context payloads.</li><li>Supervisor and process-runner timeout handles no longer keep validation processes alive.</li><li>Analyst create-card handling now strips card IDs before fallback type extraction and refines LLM tool parameters from explicit user wording, so <code>code card under goal-2</code> remains type <code>code</code> with parent <code>goal-2</code>.</li><li>WebSocket auth rejection close timers and server-startup fetch sockets are cleaned up so server integration tests exit cleanly under <code>--detectOpenHandles</code>.</li></ul><h2 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h2><ul><li><code>npm run typecheck</code></li><li><code>NODE_OPTIONS=--experimental-vm-modules npx jest tests/analyst.test.ts tests/utils/active-runtime.test.ts --runInBand --detectOpenHandles</code></li><li><code>npm run web:test -- src/__tests__/dashboard-view.test.ts</code></li><li><code>NODE_OPTIONS=--experimental-vm-modules npx jest tests/agents/skills-engine.test.ts tests/agents/agent-adapter-load-skill.test.ts tests/utils/active-runtime.test.ts tests/utils/file-tree.test.ts tests/utils/llm-dispatch-e2e.test.ts tests/analyst.test.ts --runInBand --detectOpenHandles</code></li><li><code>timeout 240s env NODE_OPTIONS=--experimental-vm-modules npx jest tests/server --runInBand --detectOpenHandles</code></li><li>Full backend suite: <code>npm run typecheck &amp;&amp; npm test -- --runInBand --detectOpenHandles</code></li><li>Web/control-room sweep: <code>npm run web:test:sweep</code></li><li>Docs verification: <code>npm run docs:verify</code></li><li>Production build: <code>npm run build</code></li></ul><h2 id="live-browser-validation" tabindex="-1">Live Browser Validation <a class="header-anchor" href="#live-browser-validation" aria-label="Permalink to &quot;Live Browser Validation&quot;">​</a></h2><p>After rebuilding and restarting <code>saivage-v3-target.service</code>, the live Dashboard analyst conversation was exercised through the browser:</p><ol><li>Asked the analyst to show current cards with a unique marker. The message was persisted once and the analyst returned the live card tree.</li><li>Asked it to create a new goal under the project. It created <code>goal-2</code> under <code>project</code> without the previous <code>Parent card &#39;undefined&#39;</code> failure.</li><li>Asked it to create a code card under <code>goal-2</code>. The first live pass exposed the type-confusion issue above, which was fixed and redeployed.</li><li>Repeated the code-card creation. It created <code>code-1</code> under <code>goal-2</code> with type <code>code</code>.</li><li>Asked it to delete the validation subtree. The analyst produced a destructive-action preview, accepted confirmation, and deleted <code>goal-2</code>, <code>goal-3</code>, and <code>code-1</code>.</li></ol><p>The live runtime remained healthy and idle after cleanup, and the temporary validation cards were removed from the card store.</p>',15)])])}const m=t(n,[["render",r]]);export{h as __pageData,m as default};
